(()=>{const zh=document.documentElement.lang.startsWith('zh'),el=k=>document.getElementById('E05-'+k),defaults={diffusivity:1,thickness:.5,partition:.5};let p={...defaults};function state(){const D=p.diffusivity*1e-6,L=p.thickness/10,P=D*p.partition/L;return {...p,fluxHourly:P*100*3600,lagMinutes:L*L/(6*D*60),P_cm_s:P};}function mass(minutes){if(minutes===0)return 0;const D=p.diffusivity*1e-6,L=p.thickness/10,t=minutes*60;let sum=0;for(let n=1;n<=100;n++)sum+=(-1)**n/n**2*Math.exp(-D*n*n*Math.PI**2*t/L**2);return Math.max(0,D*p.partition*100/L*(t-L*L/(6*D)-2*L*L/(Math.PI**2*D)*sum));}function render(){for(const k of ['diffusivity','thickness','partition']){el(k).value=p[k];el(k+'-value').textContent=p[k];}const s=state(),max=Math.max(1,mass(120)*1.1),x=t=>85+t*5.3,y=q=>330-q*270/max;let g='<rect width="800" height="420" fill="#faf9f5"/>';for(let t=0;t<=120;t+=30)g+=`<text x="${x(t)}" y="355" text-anchor="middle" font-size="15">${t}</text>`;for(let i=0;i<=4;i++){const v=i*max/4;g+=`<path d="M85 ${y(v)}H721" stroke="#dce4e7"/><text x="73" y="${y(v)+5}" text-anchor="end" font-size="15">${v.toFixed(2)}</text>`;}let d='';for(let t=0;t<=120;t++)d+=`${t?'L':'M'}${x(t)} ${y(mass(t))}`;g+=`<path d="${d}" fill="none" stroke="#186e83" stroke-width="3"/>`;if(s.lagMinutes<120)g+=`<path d="M${x(s.lagMinutes)} 330 L${x(120)} ${y(s.fluxHourly*(120-s.lagMinutes)/60)}" stroke="#cd803f" stroke-width="2" stroke-dasharray="6 5" fill="none"/>`;g+=`<text x="85" y="28" font-size="16">${zh?'蓝：完整过渡；橙虚线：稳态外推':'Blue: full transient; orange dashed: steady extrapolation'}</text><text x="400" y="403" text-anchor="middle" font-size="17">${zh?'时间 / min':'Time / min'}</text><text x="23" y="210" transform="rotate(-90 23 210)" text-anchor="middle" font-size="17">${zh?'接收质量 / μg':'Received mass / μg'}</text>`;el('plot').innerHTML=g;el('readout').textContent=zh?`稳态通量 ${s.fluxHourly.toFixed(3)} μg/(cm²·h)，时间滞后 ${s.lagMinutes.toFixed(3)} min，P=${s.P_cm_s.toExponential(3)} cm/s。`:`Steady flux ${s.fluxHourly.toFixed(3)} μg/(cm²·h), time lag ${s.lagMinutes.toFixed(3)} min, P=${s.P_cm_s.toExponential(3)} cm/s.`;}function set(n){if('diffusivity'in n)p.diffusivity=Math.min(4,Math.max(.25,+n.diffusivity));if('thickness'in n)p.thickness=Math.min(1,Math.max(.25,+n.thickness));if('partition'in n)p.partition=Math.min(2,Math.max(.1,+n.partition));render();return state();}for(const k of ['diffusivity','thickness','partition'])el(k).addEventListener('input',()=>set({[k]:+el(k).value}));el('thicker').addEventListener('click',()=>set({thickness:p.thickness*2}));el('reset').addEventListener('click',()=>{p={...defaults};render();});window.CourseLab={set,state,reset(){p={...defaults};render();return state();}};render();})();
